final class Memo {
    private var cache: [Key: Value] = [:]
    private let lock = NSLock()

    func value(for key: Key) -> Value {
        lock.lock(); defer { lock.unlock() }
        if let hit = cache[key] { return hit }   // subscript is optional: miss vs stored value
        let computed = compute(key)               // runs under the lock: keep it short
        cache[key] = computed
        return computed
    }
}

